                    '        \u041F\u041E \u0414\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u0422\u043E\u0432\u0430\u0440\u044B.\u041D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430 = \u041E\u0441\u0442\u0430\u0442\u043A\u0438.\u041D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430',
