                    '    \u0417\u0430\u043F\u0440\u043E\u0441.\u0422\u0435\u043A\u0441\u0442 = "\u0412\u042B\u0411\u0420\u0410\u0422\u042C \u0426\u0435\u043D\u0430 \u0418\u0417 \u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0421\u0432\u0435\u0434\u0435\u043D\u0438\u0439.\u0426\u0435\u043D\u044B\u041D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u044B.\u0421\u0440\u0435\u0437\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445(&\u041F\u0435\u0440\u0438\u043E\u0434, \u041D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430 = &\u041D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430)";',
                    '    \u0417\u0430\u043F\u0440\u043E\u0441.\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440("\u041F\u0435\u0440\u0438\u043E\u0434", \u0422\u0435\u043A\u0443\u0449\u0430\u044F\u0414\u0430\u0442\u0430());',
